import { _decorator, Component, Sprite, SpriteFrame } from 'cc';
import type { EntityView } from '../../Engine/ViewRegistry';
import type { Entity } from '../../Engine/Entity';
import type { BuildingEntity } from '../Entity/BuildingEntity';

const { ccclass, property } = _decorator;

@ccclass('BuildingView')
export class BuildingView extends Component implements EntityView {
    // 外部可以在编辑器里拖不同建筑的图片进来
    @property(SpriteFrame) stallSprite: SpriteFrame = null!;
    @property(SpriteFrame) portalSprite: SpriteFrame = null!;

    private _building: BuildingEntity = null!;
    private _sprite: Sprite = null!;

    onLoad() {
        this._sprite = this.getComponent(Sprite)!;
    }

    bind(entity: Entity): void {
        this._building = entity as BuildingEntity;
        
        // 根据实体类型，切换对应的图片
        if (this._building.typeId === 'stall') {
            this._sprite.spriteFrame = this.stallSprite;
        } else if (this._building.typeId === 'portal') {
            this._sprite.spriteFrame = this.portalSprite;
        }

        this.sync(0); // 绑定完立刻同步一次位置
    }

    sync(dt: number): void {
        if (!this._building) return;
        
        // 坐标已经在 BuildSystem 里通过 gridToWorld 算好并赋值给 x, y 了
        this.node.setPosition(this._building.x, this._building.y);
    }

    unbind(): void {
        this._building = null!;
    }
}